const LEVELS=window.MAGIC_FOREST_LEVELS,PROGRESS=window.MAGIC_FOREST_PROGRESS,SAVE=window.MAGIC_FOREST_SAVE,KEY='magicForestSaveV2';
let save=SAVE.load(localStorage,KEY);
if(save.stars?.[5]&&save.unlocked<6){save.unlocked=6;localStorage.setItem(KEY,JSON.stringify(save))}
const app=document.querySelector('#app');let audio,cancelProfile;document.addEventListener('click',event=>{if(event.target?.id==='cancelProfile')home()});
function playerName(){return save.player?.name?.trim()||'แบมแบม'}
function personalize(value){return String(value).replaceAll('แบมแบม',playerName())}
function applyPlayerCopy(from='แบมแบม'){if(!save.player)return;const visit=value=>{if(Array.isArray(value))return value.forEach(visit);if(value&&typeof value==='object')return Object.keys(value).forEach(k=>{if(typeof value[k]==='string')value[k]=value[k].replaceAll(from,playerName());else visit(value[k])})};visit(LEVELS);visit(window.WORLD_ONE_ENDING);visit(window.WORLD_TWO_ENDING)}
const ITEM_BOOK={
 'เมล็ดแสง':{art:'golden-star.png',note:'เก็บพลังจากประตูเถาวัลย์ ใช้ปลุกสิ่งที่หลับใหล'},
 'เศษผลึกฟ้า':{art:'echo-crystal.png',note:'เศษหัวใจของป่า ส่งเสียงใสเมื่ออยู่ใกล้เวทมนตร์'},
 'ใบปัญญา':{art:'explorer-compass.png',note:'ใบไม้ที่ชี้ทางให้ผู้กล้าซึ่งคิดอย่างรอบคอบ'},
 'หยดน้ำค้างแท้':{art:'moon.png',note:'น้ำค้างจากถ้ำเสียงโกหก ส่องแสงเมื่อได้ยินความจริง'},
 'ผลึกหัวใจชิ้นที่ 1':{art:'adventure-map.png',note:'กุญแจชิ้นแรกสู่หัวใจแห่งป่า และเส้นทางสู่อาณาจักรถัดไป'}
 ,'ศิลาจันทร์คู่':{art:'moon.png',note:'หินสองสีที่รวมแสงเป็นสะพานข้ามทะเลสาบแห่งดวงจันทร์'},
 'แกนคริสตัลสมบูรณ์':{art:'echo-crystal.png',note:'แกนกลางจากคริสตัล 457 ชิ้นที่รอดจากเวทมนตร์ทำลาย'}
 ,'เกล็ดรุ้งแปดสี':{art:'golden-star.png',note:'ประกายจากเกล็ด 56 ชิ้นของปลาสายรุ้งทั้งแปดตัว'}
 ,'ตราประตูใบไม้':{art:'explorer-compass.png',note:'ตราที่เกิดจากใบไม้ทองและเงินรวมกันครบ 445 ใบ'}
 ,'เม็ดทรายแห่งโอเอซิส':{art:'golden-star.png',note:'ทราย 455 กิโลกรัมที่เหลือและช่วยปลุกโอเอซิสกลับคืนมา'}
};
function itemInfo(savedItem){const name=savedItem.replace(/^\S+\s+/,'');return {name,...(ITEM_BOOK[name]||{art:'golden-star.png',note:'ของวิเศษจากการผจญภัย'})}}
function itemArt(savedItem,extra=''){const item=itemInfo(savedItem);return `<img class="item-art ${extra}" src="assets/items/${item.art}" alt="${item.name}">`}
function levelArt(level,extra=''){const files=['level-1-vine-gate.png','level-2-stone-bridge.png','level-3-dancing-mushrooms.png','level-4-crystal-cave.png','level-5-heart-tree.png','level-6-moon-lake.png','level-7-crystal-cave.png','level-8-rainbow-waterfall.png','level-9-leaf-tunnel.png','level-10-magic-desert.png'];const src=files[level.id-1]?`assets/levels/${files[level.id-1]}`:'assets/items/moon.png';return `<img class="level-art ${extra}" src="${src}" alt="${level.title}">`}
function hotspotArt(level,index,extra=''){const files={1:['level-1-red-flowers.png','level-1-blue-flowers.png','level-1-magic-rune.png'],2:['level-2-stone-pile.png','level-2-repaired-bridge.png','level-2-shadow-footprints.png'],3:['level-3-pink-mushrooms.png','level-3-blue-mushrooms.png','level-3-fluffy.png'],4:['level-4-dew-pool.png','level-4-silver-feather.png','level-4-echo.png'],5:['level-5-butterflies.png','level-5-tree-heart.png','level-5-shadow-vines.png','level-5-shadow-crystal.png']};if(files[level.id])return `<img class="hotspot-art ${extra}" src="assets/hotspots/${files[level.id][index]}" alt="">`;return `<span class="hotspot-emoji ${extra}">${level.hotspots[index].icon}</span>`}
function persist(){save=SAVE.stamp(save);localStorage.setItem(KEY,JSON.stringify(save))}
function tone(freq=520,d=.12){if(!save.sound)return;audio||=new(window.AudioContext||window.webkitAudioContext)();const o=audio.createOscillator(),g=audio.createGain();o.frequency.value=freq;o.type='sine';g.gain.setValueAtTime(.07,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+d);o.connect(g).connect(audio.destination);o.start();o.stop(audio.currentTime+d)}
function successFanfare(){[[660,80,.12],[820,210,.14],[1040,360,.28]].forEach(([freq,delay,duration])=>setTimeout(()=>tone(freq,duration),delay))}
function networkLabel(){return navigator.onLine?'🌐 <span>ออนไลน์</span>':'📦 <span>ออฟไลน์พร้อมเล่น</span>'}
function updateNetworkStatus(){const badge=document.querySelector('[data-network]');if(!badge)return;badge.innerHTML=networkLabel();badge.setAttribute('aria-label',navigator.onLine?'สถานะออนไลน์':'สถานะออฟไลน์ เกมพร้อมเล่นต่อ')}
function topbar(back){return `<header class="topbar">${back?'<button class="icon-btn" data-back aria-label="ย้อนกลับ">‹</button>':''}<div class="brand"><img src="assets/items/golden-star.png" alt=""> ผจญภัยในป่าเวทมนตร์</div><button class="pill collection-pill" data-inventory aria-label="เปิดกระเป๋าของสะสม"><img src="assets/items/adventure-map.png" alt=""> <b>${save.items.length}/${LEVELS.length}</b></button><div class="pill" aria-label="ผลึกเวทมนตร์ ${save.crystals} เม็ด">💎 <b>${save.crystals}</b></div><div class="pill network-pill" data-network role="status" aria-live="polite" aria-label="${navigator.onLine?'สถานะออนไลน์':'สถานะออฟไลน์ เกมพร้อมเล่นต่อ'}">${networkLabel()}</div><button class="icon-btn" data-sound aria-label="เสียงประกอบ" aria-pressed="${save.sound}">${save.sound?'🔊':'🔇'}</button></header>`}
function common(backFn=map){updateNetworkStatus();document.querySelector('[data-sound]')?.addEventListener('click',e=>{save.sound=!save.sound;persist();e.currentTarget.textContent=save.sound?'🔊':'🔇';e.currentTarget.setAttribute('aria-pressed',String(save.sound));tone()});document.querySelector('[data-back]')?.addEventListener('click',backFn);document.querySelectorAll('[data-inventory]').forEach(b=>b.addEventListener('click',showInventory));const profileButton=document.querySelector('#profileBtn');if(profileButton&&!document.querySelector('#parentBtn')){profileButton.insertAdjacentHTML('afterend','<button class="secondary" id="parentBtn">มุมผู้ปกครอง</button>');document.querySelector('#parentBtn').onclick=showParentDashboard}queueMicrotask(enhancePuzzleAccessibility)}
function enhancePuzzleAccessibility(){const puzzle=document.querySelector('#puzzle');if(!puzzle)return;const title=document.querySelector('.mission h1')?.textContent||'ปริศนาตัวเลข';puzzle.setAttribute('role','group');puzzle.setAttribute('aria-label',title);const feedback=document.querySelector('#feedback');feedback?.setAttribute('role','status');feedback?.setAttribute('aria-atomic','true');const groups=[['.magic-tiles','ตัวเลือกคำตอบ'],['.digit-keys','แป้นตัวเลข'],['.number-wheels','วงล้อค่าประจำหลัก'],['.butterfly-swarm','ฝูงผีเสื้อแห่งแสง'],['.crystal-shards','เศษคริสตัล'],['.place-value-slots','ช่องค่าประจำหลัก'],['.fish-school','ฝูงปลาสายรุ้ง'],['.leaf-bundles','มัดใบไม้'],['.sand-scoops','ตวงทรายเวทมนตร์']];groups.forEach(([selector,label])=>{const group=puzzle.querySelector(selector);if(group){group.setAttribute('role','group');group.setAttribute('aria-label',label)}});puzzle.querySelectorAll('.magic-tiles .tile').forEach(button=>button.setAttribute('aria-label',`เลือกคำตอบ ${button.textContent.trim()}`));puzzle.querySelectorAll('.digit-keys .tile').forEach(button=>button.setAttribute('aria-label',`ใส่เลข ${button.textContent.trim()}`));puzzle.querySelectorAll('.choice[data-v]').forEach(button=>button.setAttribute('aria-label',`ตอบ ${button.textContent.trim()}`));if(feedback&&puzzle.querySelector('#magicSlot'))new MutationObserver(()=>{if(document.querySelector('#castChoice')?.disabled)requestAnimationFrame(()=>puzzle.querySelector('.magic-tiles .tile')?.focus())}).observe(feedback,{childList:true});puzzle.querySelector('button:not([disabled])')?.focus()}
function collectionCard(l){const saved=save.items.find(x=>x.endsWith(l.reward));if(!saved)return `<div class="collection-card locked-item"><div class="item-silhouette">?</div><div><strong>ของวิเศษที่ยังไม่พบ</strong><p>ผ่านตอนที่ ${l.id} เพื่อเปิดเผย</p></div></div>`;const info=itemInfo(saved);return `<div class="collection-card">${itemArt(saved)}<div><strong>${info.name}</strong><p>${info.note}</p></div></div>`}
function collectionWorld(world,title){const levels=LEVELS.filter(l=>(l.world||1)===world),found=levels.filter(l=>save.items.some(x=>x.endsWith(l.reward))).length;return `<section class="collection-world collection-world-${world}"><div class="collection-world-title"><h3>${title}</h3><span>${found}/${levels.length} ชิ้น</span></div><div class="collection-grid">${levels.map(collectionCard).join('')}</div></section>`}
function showInventory(){document.body.insertAdjacentHTML('beforeend',`<div class="collection-modal" role="dialog" aria-modal="true" aria-label="กระเป๋านักผจญภัย"><section class="collection-panel"><button class="collection-close" aria-label="ปิดกระเป๋า">×</button><div class="eyebrow">ของวิเศษจากทุกการผจญภัย</div><h2>กระเป๋านักผจญภัย</h2><p class="collection-summary">ค้นพบแล้ว ${save.items.length} จาก ${LEVELS.length} ชิ้น · ผลึก ${save.crystals} เม็ด</p>${collectionWorld(1,'World 1 · ป่าแห่งตัวเลข')}${collectionWorld(2,'World 2 · เส้นทางสู่อาณาจักรเห็ด')}</section></div>`);const modal=document.querySelector('.collection-modal'),close=()=>{modal.remove();document.removeEventListener('keydown',onKey)},onKey=e=>{if(e.key==='Escape')close()};modal.querySelector('.collection-close').onclick=close;modal.onclick=e=>{if(e.target===modal)close()};document.addEventListener('keydown',onKey);modal.querySelector('.collection-close').focus()}
function parentSkill(label,icon,ids){const completed=ids.filter(id=>save.stars[id]).length,stars=ids.reduce((total,id)=>total+(save.stars[id]||0),0),percent=Math.round(stars/(ids.length*3)*100);return `<article class="parent-skill"><span>${icon}</span><div><strong>${label}</strong><small>ผ่าน ${completed}/${ids.length} ด่าน · ${stars}/${ids.length*3} ดาว</small><i><b style="width:${percent}%"></b></i></div></article>`}
function showParentDashboard(){const completed=LEVELS.filter(level=>save.stars[level.id]).length,totalStars=Object.values(save.stars).reduce((sum,stars)=>sum+stars,0),next=LEVELS.find(level=>level.id<=save.unlocked&&!save.stars[level.id]);document.body.insertAdjacentHTML('beforeend',`<div class="collection-modal parent-modal" role="dialog" aria-modal="true" aria-label="มุมผู้ปกครอง"><section class="collection-panel parent-panel"><button class="collection-close" aria-label="ปิดมุมผู้ปกครอง">×</button><div class="eyebrow">ภาพรวมการเรียนรู้ของ ${playerName()}</div><h2>มุมผู้ปกครอง</h2><p class="collection-summary">ข้อมูลนี้บันทึกในอุปกรณ์เครื่องนี้เท่านั้น</p><div class="parent-totals"><article><strong>${completed}/${LEVELS.length}</strong><span>ด่านที่ผ่าน</span></article><article><strong>${totalStars}/${LEVELS.length*3}</strong><span>ดาวสะสม</span></article><article><strong>${save.items.length}/${LEVELS.length}</strong><span>ของวิเศษ</span></article></div><div class="parent-skills">${parentSkill('การบวก','➕',[1,3,6,9])}${parentSkill('การลบ','➖',[2,4,7,10])}${parentSkill('การคูณ','✖️',[5,8])}</div><div class="parent-next"><strong>${next?'แนะนำให้เล่นต่อ':'ผ่านเนื้อหาปัจจุบันครบแล้ว'}</strong><span>${next?`ตอนที่ ${next.id} · ${next.title}`:'รอการผจญภัยบทถัดไป'}</span></div></section></div>`);const modal=document.querySelector('.parent-modal'),close=()=>{modal.remove();document.removeEventListener('keydown',onKey)},onKey=e=>{if(e.key==='Escape')close()};modal.querySelector('.collection-close').onclick=close;modal.onclick=e=>{if(e.target===modal)close()};document.addEventListener('keydown',onKey);modal.querySelector('.collection-close').focus()}
function characterArt(who,fallback,extra=''){if(who.includes('ชิป')&&who.includes('ฟลัฟฟี่'))return `<span class="character-pair"><img src="assets/characters/chip.png" alt="ชิป"><img src="assets/characters/fluffy.png" alt="ฟลัฟฟี่"></span>`;if(who.includes('แบมแบม')||who.includes(playerName())){const file=save.player?.gender==='girl'?'bambam-girl.png':'bambam.png';return `<img class="character-art ${extra}" src="assets/characters/${file}" alt="${playerName()} นักผจญภัยตัวน้อย">`}if(who.includes('ชิป'))return `<img class="character-art ${extra}" src="assets/characters/chip.png" alt="ชิป กระรอกผู้ช่วยของ${playerName()}">`;if(who.includes('ฟลัฟฟี่'))return `<img class="character-art ${extra}" src="assets/characters/fluffy.png" alt="ฟลัฟฟี่ กระต่ายนักผจญภัย">`;if(who.includes('ต้นไม้'))return `<img class="character-art ${extra}" src="assets/characters/silver-tree.png" alt="ต้นไม้สีเงินผู้พิทักษ์ป่าเวทมนตร์">`;if(who.includes('พ่อมด'))return `<img class="character-art ${extra}" src="assets/characters/shadow-wizard.png" alt="พ่อมดเงาจอมเจ้าเล่ห์">`;if(fallback==='🌙')return `<img class="character-art ${extra}" src="assets/items/moon.png" alt="ดวงจันทร์เวทมนตร์">`;return fallback}
function starRating(stars){return `<span class="rating-stars" aria-label="${stars} ดาว">${Array.from({length:3},(_,i)=>`<img class="${i<stars?'earned':'empty'}" src="assets/items/golden-star.png" alt="">`).join('')}</span>`}
const PROLOGUE=[
 {who:'ผู้เล่า',face:'🌙',text:'ค่ำวันหนึ่ง หลังเสียงระฆังโรงเรียนดัง แบมแบมได้ยินเสียงกระซิบมาจากป่าที่ไม่เคยมีใครกล้าเข้าไป'},
 {who:'แบมแบม',face:'🧒🏻',text:'เสียงนั้น… กำลังนับเลขอยู่หรือเปล่านะ? หนึ่ง… สอง… แล้วทำไมถึงหยุดล่ะ?'},
 {who:'ต้นไม้สีเงิน',face:'🌳',text:'ผู้ที่ได้ยินเสียงของตัวเลข โปรดช่วยข้าด้วย หัวใจแห่งตัวเลขกำลังแตกสลาย!'},
 {who:'ชิป',face:'🐿️',text:'ว้าย! เธอได้ยินจริง ๆ ด้วย ฉันชื่อชิป พ่อมดเงาขโมยผลึกไป ถ้าเราไม่รีบ ป่าทั้งผืนจะลืมวิธีนับ!'},
 {who:'แบมแบม',face:'🧒🏻',text:'งั้นเราไปเอาตัวเลขกลับมากันเถอะ ต่อให้มีหนึ่งร้อยปริศนา ฉันก็ไม่ถอย!'}
];
function profileSetup(){const editing=!!save.player,previousName=playerName();let gender=save.player?.gender||'boy';app.innerHTML=`<section class="profile-screen"><div class="profile-card"><div class="eyebrow">${editing?'โปรไฟล์นักผจญภัย':'สร้างนักผจญภัยของคุณ'}</div><h1>${editing?'ปรับลุคก่อนเดินทางต่อ':'ใครจะได้ยินเสียงตัวเลข?'}</h1><p>เลือกตัวละครและตั้งชื่อ ชื่อนี้จะปรากฏตลอดเรื่องราว</p><div class="character-choice" role="group" aria-label="เลือกตัวละคร"><button class="${gender==='boy'?'selected':''}" data-gender="boy" aria-pressed="${gender==='boy'}"><img src="assets/characters/bambam.png" alt=""><strong>ตัวละครผู้ชาย</strong></button><button class="${gender==='girl'?'selected':''}" data-gender="girl" aria-pressed="${gender==='girl'}"><img src="assets/characters/bambam-girl.png" alt=""><strong>ตัวละครผู้หญิง</strong></button></div><label class="name-field">ชื่อของนักผจญภัย<input id="playerNameInput" maxlength="12" autocomplete="off" placeholder="เช่น แบมแบม" value="${save.player?.name||''}"></label><div class="name-error" id="nameError" role="alert" aria-live="polite"></div><div class="profile-actions">${editing?'<button class="secondary" id="cancelProfile">ยกเลิก</button>':''}<button class="primary profile-start" id="savePlayer">${editing?'บันทึกโปรไฟล์':'เริ่มการผจญภัย ✦'}</button></div></div></section>`;document.querySelectorAll('[data-gender]').forEach(b=>b.onclick=()=>{gender=b.dataset.gender;document.querySelectorAll('[data-gender]').forEach(x=>{const selected=x===b;x.classList.toggle('selected',selected);x.setAttribute('aria-pressed',String(selected))})});cancelProfile?.addEventListener('click',home);savePlayer.onclick=()=>{const name=playerNameInput.value.trim().replace(/[<>&"']/g,'');if(!name){nameError.textContent='พิมพ์ชื่อก่อนออกเดินทางนะ';playerNameInput.focus();return}save.player={name:name.slice(0,12),gender};persist();applyPlayerCopy(previousName);home()};playerNameInput.onkeydown=e=>{if(e.key==='Enter')savePlayer.click()};playerNameInput.focus()}
function home(){app.innerHTML=`<section class="screen">${topbar()}<div class="hero"><div class="intro"><div class="eyebrow">บทที่ 1 · เสียงกระซิบจากต้นไม้สีเงิน</div><h1>หัวใจแห่ง<br>ตัวเลขหายไป!</h1><p>เมื่อป่าเริ่มลืมวิธีนับ ${playerName()}ต้องร่วมมือกับชิปและฟลัฟฟี่ ตามหาผลึกที่ถูกพ่อมดเงาขโมยไป</p><div class="actions"><button class="primary" id="start">${save.storySeen?'เดินทางต่อ':'เปิดเรื่องราว'}</button><button class="secondary" id="mapBtn"><img class="button-item" src="assets/items/adventure-map.png" alt=""> แผนที่</button><button class="secondary" id="profileBtn">เปลี่ยนชื่อ/ตัวละคร</button></div><button class="inventory-shelf" data-inventory><span>${save.items.length?'ของวิเศษที่พบแล้ว':'กระเป๋ายังว่างอยู่'}</span><span class="inventory-icons">${save.items.length?save.items.map(x=>itemArt(x)).join(''):'ออกผจญภัยเพื่อค้นหาของวิเศษ ✦'}</span></button></div><div class="companions"><div class="avatar art-avatar hero-player">${characterArt('แบมแบม','🧒🏻')}<small>${playerName()}</small></div><div class="avatar art-avatar">${characterArt('ชิป','🐿️')}<small>ชิป</small></div><div class="avatar art-avatar">${characterArt('ฟลัฟฟี่','🐇')}<small>ฟลัฟฟี่</small></div></div></div></section>`;common();start.onclick=()=>save.storySeen?map():story(PROLOGUE,()=>{save.storySeen=true;persist();map()});mapBtn.onclick=map;profileBtn.onclick=profileSetup}
function story(lines,done,i=0){const line=lines[i];app.innerHTML=`<section class="story-screen">${topbar(true)}<div class="story-stage"><img class="story-magic" src="assets/items/golden-star.png" alt="ประกายเวทมนตร์"><div class="speaker-face">${characterArt(line.who,line.face)}</div><div class="dialogue"><div class="speaker">${personalize(line.who)}</div><p>${personalize(line.text)}</p><button class="primary" id="nextLine">${i===lines.length-1?'ออกเดินทาง':'ต่อไป'}</button></div><button class="skip" id="skip">ข้ามเรื่องราว</button></div></section>`;common(home);nextLine.onclick=()=>{tone(480+i*40);i<lines.length-1?story(lines,done,i+1):done()};skip.onclick=done;nextLine.focus()}
function nextAdventure(){return LEVELS.find(l=>l.id<=save.unlocked&&!save.stars[l.id])||null}
function stageCard(l,recommendedId){const locked=l.id>save.unlocked,stars=save.stars[l.id]||0,current=l.id===recommendedId;return `<button class="stage world-${l.world||1} ${locked?'locked':''} ${stars?'done':''} ${current?'current':''}" data-level="${l.id}" ${locked?'disabled':''}>${current?'<span class="current-badge">ไปต่อที่นี่ ✦</span>':stars?'<span class="complete-badge">ผ่านแล้ว ✓</span>':''}<span class="num">ตอนที่ ${l.id} ${locked?'· 🔒':''}</span>${levelArt(l,'stage-art')}<h2>${l.title}</h2><p>${l.teaser}</p>${starRating(stars)}</button>`}
function worldMap(world,title,subtitle,recommendedId){const levels=LEVELS.filter(l=>(l.world||1)===world),completed=levels.filter(l=>save.stars[l.id]).length,stars=levels.reduce((total,l)=>total+(save.stars[l.id]||0),0),percent=completed/levels.length*100,done=completed===levels.length;return `<section class="world-map world-map-${world} ${done?'world-complete':''}"><div class="world-map-head"><div><div class="eyebrow">${subtitle}</div><h2>${title}</h2><p>${done?`พิชิตครบแล้ว! ผลึกหัวใจชิ้นที่ ${world} กลับคืนมา ✦`:`ผ่านแล้ว ${completed} จาก ${levels.length} ตอน`}</p></div><div class="world-progress" aria-label="ผ่าน ${completed} จาก ${levels.length} ตอน"><strong>${completed}/${levels.length}</strong><span>⭐ ${stars}/${levels.length*3}</span><div><i style="width:${percent}%"></i></div></div></div><div class="stage-grid">${levels.map(l=>stageCard(l,recommendedId)).join('')}</div></section>`}
function map(){const next=nextAdventure(),complete=!next,totalStars=LEVELS.reduce((sum,l)=>sum+(save.stars[l.id]||0),0),newPlayer=!Object.keys(save.stars||{}).length;app.innerHTML=`<section class="screen">${topbar()}<div class="map-wrap"><div class="map-head"><div><div class="eyebrow">${complete?'ภารกิจสองโลกสำเร็จแล้ว':'เส้นทางตามหาผลึกทั้งสิบชิ้น'}</div><h1>แผนที่ป่าเวทมนตร์</h1><p>${complete?'ผลึกหัวใจสองชิ้นกลับคืนมาแล้ว การผจญภัยบทถัดไปกำลังก่อตัว':'ทุกโลกมีเรื่องราว ของวิเศษ และพลังตัวเลขแบบใหม่รออยู่'}</p></div><div class="map-actions"><button class="secondary" id="homeBtn">บ้านต้นไม้</button>${complete?'<button class="primary" id="endingBtn">ดูฉากจบ World 2 อีกครั้ง ✦</button>':`<button class="primary" id="continueBtn">เล่นตอนที่ ${next.id} ต่อ ▶</button>`}</div></div>${newPlayer?'<section class="first-quest-guide" aria-label="วิธีเริ่มเล่น"><strong>เริ่มการผจญภัยใน 3 ขั้น</strong><ol><li><b>1</b><span>เลือกตอนที่ 1</span></li><li><b>2</b><span>แตะสำรวจหาเบาะแส</span></li><li><b>3</b><span>ใช้พลังตัวเลขแก้ปริศนา</span></li></ol></section>':''}${complete?`<section class="journey-complete"><div><span>🏆</span><div><small>การเดินทางปัจจุบัน</small><h2>พิชิตครบ 10 ตอน!</h2><p>ของวิเศษ ${save.items.length}/10 · ผลึก ${save.crystals} เม็ด · ดาว ${totalStars}/30</p></div></div><div class="next-world-lock"><span>🔒</span><div><small>บทถัดไป</small><strong>World 3 · อาณาจักรเห็ดยักษ์</strong><p>กำลังเตรียมการผจญภัย</p></div></div></section>`:''}${worldMap(1,'World 1 · ป่าแห่งตัวเลข','ผลึกหัวใจชิ้นที่ 1',next?.id)}${worldMap(2,'World 2 · เส้นทางสู่อาณาจักรเห็ด','ผลึกหัวใจชิ้นที่ 2',next?.id)}</div></section>`;common();homeBtn.onclick=home;if(complete)endingBtn.onclick=()=>story(window.WORLD_TWO_ENDING,map);else continueBtn.onclick=()=>beginLevel(next.id);document.querySelectorAll('[data-level]').forEach(b=>b.onclick=()=>beginLevel(+b.dataset.level))}
function beginLevel(id){const l=LEVELS[id-1];story(l.dialogue,()=>explore(id))}
function explore(id){const l=LEVELS[id-1],found=new Set();app.innerHTML=`<section class="explore ${l.scene}">${topbar(true)}<div class="quest-card"><span>ภารกิจ</span><strong>${l.quest}</strong><div class="clue-progress"><div id="clueProgressText" aria-live="polite"><b id="clueCount">0</b> / ${l.required} เบาะแส</div><span id="clueProgressMeter" role="progressbar" aria-label="ความคืบหน้าเบาะแส" aria-valuemin="0" aria-valuemax="${l.required}" aria-valuenow="0"><i id="clueProgressBar"></i></span></div></div><div class="explore-copy"><div class="eyebrow">ตอนที่ ${l.id}</div><h1>${l.title}</h1><p>${l.exploreText}</p><p class="explore-instruction" id="exploreHelp">แตะจุดเรืองแสง หรือใช้ Tab แล้วกด Enter เพื่อสำรวจ</p></div><div class="hotspots" role="group" aria-label="จุดสำรวจ">${l.hotspots.map((h,n)=>`<button class="hotspot ${l.id<=3?'illustrated-hotspot':''}" data-spot="${n}" aria-label="สำรวจ ${h.label}" aria-describedby="exploreHelp" aria-pressed="false">${hotspotArt(l,n)}<small>${h.label}</small><i class="discovery-spark" aria-hidden="true">✦</i></button>`).join('')}</div><div class="clue-box" id="clue" role="status" aria-live="polite">${characterArt('ชิป','🐿️','clue-character')}<p>ชิป: ลองแตะสิ่งที่น่าสงสัยในฉากดูสิ!</p></div><button class="primary solve-btn" id="solve" aria-describedby="clueProgressText" disabled>ใช้พลังตัวเลข</button></section>`;common(map);document.querySelectorAll('[data-spot]').forEach(b=>b.onclick=()=>{const n=+b.dataset.spot,h=l.hotspots[n];if(found.has(n)){clue.innerHTML=`${hotspotArt(l,n,'clue-hotspot-art')}<p><strong>${h.label} — สำรวจแล้ว</strong><br>${h.clue}</p>`;return}found.add(n);b.classList.add('found');b.setAttribute('aria-pressed','true');b.setAttribute('aria-label',`สำรวจแล้ว ${h.label}`);clue.innerHTML=`${hotspotArt(l,n,'clue-hotspot-art')}<p><strong>${h.label}</strong><br>${h.clue}</p>`;document.querySelector('#clueCount').textContent=Math.min(found.size,l.required);document.querySelector('#clueProgressBar').style.width=`${Math.min(found.size/l.required,1)*100}%`;document.querySelector('#clueProgressMeter').setAttribute('aria-valuenow',Math.min(found.size,l.required));tone(560+n*70);if(found.size>=l.required){solve.disabled=false;solve.textContent='ใช้พลังตัวเลข ✦';document.querySelector('.clue-progress').classList.add('complete');clue.insertAdjacentHTML('beforeend','<span class="sr-only">พบเบาะแสครบแล้ว ปุ่มใช้พลังตัวเลขพร้อมใช้งาน</span>')}});solve.onclick=()=>play(id)}
function play(id){const l=LEVELS[id-1];let tries=0,digits='',wheels=[6,0,0],echoValue=732,echoSteps=0,wingLight=0,litButterflies=0,crystalValue=915,crystalSteps=0,fishLit=0,rainbowScales=0,leafTotal=189,leafSteps=0,sandTotal=600,sandSteps=0;app.innerHTML=`<section class="play">${topbar(true)}<div class="play-area"><article class="mission"><div class="eyebrow">เวทมนตร์แห่งตัวเลข · ตอนที่ ${l.id}</div><div class="scene-icon">${levelArt(l,'mission-art')}</div><h1>${l.puzzleTitle}</h1><p class="story">${l.story}</p><div class="prompt">${l.prompt}</div><div class="puzzle" id="puzzle"></div><div class="feedback" id="feedback" aria-live="polite"><div class="star-chance">โอกาสรอบนี้ ${starRating(3)}</div></div></article></div></section>`;common(()=>explore(id));const p=document.querySelector('#puzzle'),fb=document.querySelector('#feedback');const check=v=>{tries++;if(String(v)===String(l.answer)){tone(760,.3);finish(l,tries);return true}const possibleStars=PROGRESS.starsForTries(tries+1),hint=tries===1?l.hint1:l.hint2;tone(180,.18);fb.innerHTML=`<div class="hint-card">${characterArt('ชิป','🐿️','hint-chip')}<div><strong>${tries===1?'เกือบแล้ว ลองอีกครั้งนะ!':'ชิปมีคำใบ้เพิ่มให้'}</strong><p>${hint}</p><div class="star-chance">ถ้าตอบครั้งถัดไป จะได้ ${starRating(possibleStars)}</div></div></div>`;navigator.vibrate?.(60);return false};
if(l.type==='drag'){let selected='';p.innerHTML=`<div class="magic-choice-builder"><div class="magic-tiles">${l.choices.map(x=>`<button draggable="true" class="tile" data-v="${x}" aria-pressed="false">${x}</button>`).join('')}</div><button class="slot magic-slot" id="magicSlot" aria-disabled="true"><small>วงแหวนเวท</small><strong id="selectedMagic">แตะหรือลากคำตอบมาที่นี่</strong></button><button class="primary" id="castChoice" disabled>ส่งคำตอบลงวงแหวน ✦</button></div>`;const tiles=[...p.querySelectorAll('.tile')],selectMagic=value=>{selected=String(value);selectedMagic.textContent=selected;magicSlot.setAttribute('aria-disabled','false');castChoice.disabled=false;tiles.forEach(tile=>{const active=tile.dataset.v===selected;tile.classList.toggle('selected',active);tile.setAttribute('aria-pressed',String(active))});tone(500)};tiles.forEach(tile=>{tile.ondragstart=e=>e.dataTransfer.setData('text',tile.dataset.v);tile.onclick=()=>selectMagic(tile.dataset.v)});magicSlot.ondragover=e=>{e.preventDefault();magicSlot.classList.add('over')};magicSlot.ondragleave=()=>magicSlot.classList.remove('over');magicSlot.ondrop=e=>{e.preventDefault();magicSlot.classList.remove('over');selectMagic(e.dataTransfer.getData('text'))};magicSlot.onclick=()=>selected&&castChoice.click();castChoice.onclick=()=>{if(!check(selected)){selected='';selectedMagic.textContent='ลองเลือกคำตอบใหม่';magicSlot.setAttribute('aria-disabled','true');castChoice.disabled=true;tiles.forEach(tile=>{tile.classList.remove('selected');tile.setAttribute('aria-pressed','false')})}}}
if(l.type==='digits'){p.innerHTML=`<div class="digit-builder"><div class="slot digit-display" id="display" aria-live="polite">_ _ _</div><small id="digitStatus">เลือกตัวเลขหลักที่ 1 จาก 3</small><div class="digit-keys">${l.choices.map(x=>`<button class="tile" data-v="${x}">${x}</button>`).join('')}</div><div class="digit-actions"><button class="choice" id="backspace" disabled>⌫ ลบหลักล่าสุด</button><button class="choice" id="clear" disabled>ล้างทั้งหมด</button><button class="primary" id="submitDigits" disabled>ส่งพลังตัวเลข ✦</button></div></div>`;const refreshDigits=()=>{display.textContent=digits.padEnd(3,'_').split('').join(' ');digitStatus.textContent=digits.length===3?'ครบ 3 หลักแล้ว ตรวจดูแล้วส่งพลังได้เลย':`เลือกตัวเลขหลักที่ ${digits.length+1} จาก 3`;backspace.disabled=!digits.length;clear.disabled=!digits.length;submitDigits.disabled=digits.length!==3};p.querySelectorAll('.tile').forEach(t=>t.onclick=()=>{if(digits.length<3){digits+=t.dataset.v;tone(420+digits.length*80);refreshDigits()}});backspace.onclick=()=>{digits=digits.slice(0,-1);refreshDigits()};clear.onclick=()=>{digits='';refreshDigits()};submitDigits.onclick=()=>{const answer=digits;if(!check(answer)){digits='';refreshDigits()}}}
if(l.type==='counter'){const labels=['หลักร้อย','หลักสิบ','หลักหน่วย'];p.innerHTML=`<div class="counter-builder"><div class="number-wheels">${wheels.map((v,i)=>`<div class="wheel"><small>${labels[i]}</small><button data-wheel="${i}" data-dir="1" aria-label="เพิ่ม${labels[i]}">+</button><strong id="wheel${i}">${v}</strong><button data-wheel="${i}" data-dir="-1" aria-label="ลด${labels[i]}">−</button></div>`).join('')}</div><div class="wheel-total" aria-live="polite"><small>จำนวนที่สร้าง</small><strong id="total">600</strong><span id="wheelReading">6 ร้อย 0 สิบ 0 หน่วย</span></div><div class="counter-actions"><button class="secondary" id="resetWheels">เริ่มใหม่ที่ 600 ↻</button><button class="primary" id="cast">ร่ายเวทด้วยจำนวนนี้ ✦</button></div></div>`;const refreshWheels=(changed=-1)=>{const value=wheels[0]*100+wheels[1]*10+wheels[2];total.textContent=value;wheelReading.textContent=`${wheels[0]} ร้อย ${wheels[1]} สิบ ${wheels[2]} หน่วย`;document.querySelectorAll('.wheel').forEach((wheel,i)=>wheel.classList.toggle('turning',i===changed))};document.querySelectorAll('[data-wheel]').forEach(b=>b.onclick=()=>{const i=+b.dataset.wheel,dir=+b.dataset.dir;wheels[i]=(wheels[i]+dir+10)%10;document.querySelector('#wheel'+i).textContent=wheels[i];refreshWheels(i);tone(420+i*90)});resetWheels.onclick=()=>{wheels=[6,0,0];wheels.forEach((v,i)=>document.querySelector('#wheel'+i).textContent=v);refreshWheels();tone(360)};cast.onclick=()=>check(wheels[0]*100+wheels[1]*10+wheels[2])}
if(l.id===4){const parts=[{v:200,label:'ลบหลักร้อย',detail:'732 − 200'},{v:80,label:'ลบหลักสิบ',detail:'532 − 80'},{v:9,label:'ลบหลักหน่วย',detail:'452 − 9'}];p.innerHTML=`<div class="echo-cave"><img src="assets/characters/cave-bird.png" alt="นกถ้ำที่ดื่มน้ำค้าง"><div class="echo-pool" aria-live="polite"><small>น้ำค้างที่ยังส่องแสง</small><strong id="echoTotal">732</strong><span id="echoTrail">732</span><em id="echoProgress">ขั้นที่ 0 จาก 3</em></div></div><div class="echo-stones">${parts.map((part,i)=>`<button class="echo-stone" data-subtract="${part.v}" data-index="${i}" ${i?'disabled':''}><span>−${part.v}</span><small>${part.label}</small><i>${part.detail}</i></button>`).join('')}</div><div class="echo-actions"><button class="secondary" id="resetEcho">เริ่มใหม่ ↻</button><button class="primary" id="revealEcho" disabled>เปิดประตูด้วยคำตอบ</button></div>`;const echoButtons=[...document.querySelectorAll('[data-subtract]')],resetEchoPuzzle=()=>{echoValue=732;echoSteps=0;echoTotal.textContent=732;echoTrail.textContent='732';echoProgress.textContent='ขั้นที่ 0 จาก 3';echoButtons.forEach((button,i)=>{button.disabled=i!==0;button.classList.remove('heard')});revealEcho.disabled=true};echoButtons.forEach((b,i)=>b.onclick=()=>{if(b.disabled)return;b.disabled=true;b.classList.add('heard');echoValue-=+b.dataset.subtract;echoSteps++;echoTotal.textContent=echoValue;echoTrail.textContent+=` − ${b.dataset.subtract} = ${echoValue}`;echoProgress.textContent=`ขั้นที่ ${echoSteps} จาก 3`;tone(600-echoSteps*80,.22);if(echoButtons[i+1])echoButtons[i+1].disabled=false;else{revealEcho.disabled=false;fb.innerHTML='<div class="star-chance">ลบครบทุกหลักแล้ว คำตอบกำลังส่องแสง ✦</div>'}});resetEcho.onclick=()=>{resetEchoPuzzle();tone(360)};revealEcho.onclick=()=>check(echoValue)}
if(l.id===5){p.innerHTML=`<div class="boss-stage" id="bossStage"><div class="shadow-vines" aria-hidden="true">🕸️</div><div class="wing-meter" aria-live="polite"><small>พลังแสงจากปีก</small><strong><span id="wingCount">0</span> / 18</strong><b id="wingEquation">0 ตัว × 2 ปีก = 0</b><div><i id="wingBar"></i></div></div></div><div class="butterfly-swarm">${Array.from({length:9},(_,i)=>`<button class="light-butterfly" data-butterfly="${i}" aria-label="ปลุกผีเสื้อตัวที่ ${i+1}"><img src="assets/characters/light-butterfly.png" alt=""><small>ตัวที่ ${i+1} · +2</small></button>`).join('')}</div><div class="boss-actions"><button class="secondary" id="resetButterflies">รวมแสงใหม่ ↻</button><button class="primary final-spell" id="finalSpell" disabled>ปล่อยคาถาแสง 18 ปีก!</button></div>`;const butterflyButtons=[...document.querySelectorAll('[data-butterfly]')],resetButterflyPuzzle=()=>{litButterflies=0;wingLight=0;wingCount.textContent=0;wingEquation.textContent='0 ตัว × 2 ปีก = 0';wingBar.style.width='0%';bossStage.style.setProperty('--light-progress','0');butterflyButtons.forEach(button=>{button.disabled=false;button.classList.remove('lit')});finalSpell.disabled=true};butterflyButtons.forEach(b=>b.onclick=()=>{if(b.disabled)return;b.disabled=true;b.classList.add('lit');litButterflies++;wingLight=litButterflies*2;wingCount.textContent=wingLight;wingEquation.textContent=`${litButterflies} ตัว × 2 ปีก = ${wingLight}`;wingBar.style.width=`${wingLight/18*100}%`;bossStage.style.setProperty('--light-progress',String(wingLight/18));tone(440+litButterflies*38,.18);if(litButterflies===9){finalSpell.disabled=false;fb.innerHTML='<div class="star-chance">9 × 2 = 18 ครบแล้ว—ปล่อยคาถาแสงได้เลย! ✦</div>'}});resetButterflies.onclick=()=>{resetButterflyPuzzle();tone(360)};finalSpell.onclick=()=>check(wingLight)}
if(l.type==='repair'){const shards=[{value:50,label:'เศษยาว'},{value:8,label:'เศษเล็ก'},{value:400,label:'เศษใหญ่'}],places=[{value:400,label:'หลักร้อย'},{value:50,label:'หลักสิบ'},{value:8,label:'หลักหน่วย'}];let selected=null;p.innerHTML=`<div class="crystal-repair"><div class="crystal-core"><small>คริสตัลที่ยังสมบูรณ์</small><strong id="crystalTotal">915</strong><span id="crystalTrail">แยกเศษแตก 458 = 400 + 50 + 8</span><div class="crystal-history" id="crystalHistory" aria-live="polite"></div></div><div class="crystal-meter"><i id="crystalBar"></i></div></div><p class="repair-guide" id="repairGuide">เลือกเศษคริสตัล แล้วนำไปวางในช่องค่าประจำหลัก</p><div class="crystal-shards">${shards.map(s=>`<button data-shard data-value="${s.value}" aria-pressed="false"><span>−${s.value}</span><small>${s.label}</small></button>`).join('')}</div><div class="place-value-slots">${places.map(s=>`<button data-place="${s.value}"><small>${s.label}</small><strong>?</strong></button>`).join('')}</div><button class="primary" id="repairCrystal" disabled>รวมแสงคริสตัลที่เหลือ ✦</button>`;const shardButtons=[...p.querySelectorAll('[data-shard]')],placeButtons=[...p.querySelectorAll('[data-place]')];shardButtons.forEach(b=>b.onclick=()=>{if(b.disabled)return;selected=+b.dataset.value;shardButtons.forEach(x=>{const active=x===b;x.classList.toggle('selected',active);x.setAttribute('aria-pressed',String(active))});repairGuide.textContent=`เลือกเศษ −${selected} แล้ว ตอนนี้แตะช่องค่าประจำหลักที่ตรงกัน`;tone(500,.12)});placeButtons.forEach(slot=>slot.onclick=()=>{if(slot.disabled)return;if(selected===null){repairGuide.textContent='เลือกเศษคริสตัลด้านบนก่อนนะ';tone(190,.12);return}if(+slot.dataset.place!==selected){repairGuide.textContent=`เศษ −${selected} ยังไม่ตรงกับ ${slot.querySelector('small').textContent} ลองดูจำนวนศูนย์อีกครั้ง`;tone(180,.18);navigator.vibrate?.(50);return}const shard=shardButtons.find(b=>+b.dataset.value===selected),before=crystalValue;crystalValue-=selected;crystalSteps++;slot.disabled=true;slot.classList.add('filled');slot.querySelector('strong').textContent=`−${selected}`;shard.disabled=true;shard.classList.remove('selected');shard.classList.add('placed');shard.setAttribute('aria-pressed','false');crystalTotal.textContent=crystalValue;crystalHistory.insertAdjacentHTML('beforeend',`<span>${before} − ${selected} = <b>${crystalValue}</b></span>`);crystalBar.style.width=`${crystalSteps/3*100}%`;tone(480+crystalSteps*90,.2);selected=null;if(crystalSteps===3){repairCrystal.disabled=false;repairGuide.textContent='ครบทุกหลักแล้ว! คริสตัลสมบูรณ์เหลือ 457 ชิ้น';fb.innerHTML='<div class="star-chance">จัดเศษแตกครบแล้ว—รวมแสงเพื่อซ่อมถ้ำได้เลย ✦</div>'}else repairGuide.textContent='ถูกต้อง! เลือกเศษชิ้นถัดไป'});repairCrystal.onclick=()=>check(crystalValue)}
if(l.type==='fish'){p.innerHTML=`<div class="rainbow-score"><small>พลังเกล็ดสายรุ้ง</small><strong id="fishEquation">0 × 7 = <span id="scaleCount">0</span></strong><div><i id="rainbowBar"></i></div><p id="fishGuide">ปลุกปลาตัวที่ 1 เพื่อเริ่มขบวนแม่ 7</p></div><div class="rainbow-pattern" aria-label="รูปแบบจำนวนเพิ่มทีละ 7">${Array.from({length:8},(_,i)=>`<span data-pattern="${i}">?</span>`).join('')}</div><div class="fish-school">${Array.from({length:8},(_,i)=>`<button data-fish="${i}" aria-label="ปลุกปลาสายรุ้งตัวที่ ${i+1}" style="--fish-hue:${i*42}deg" ${i?'disabled':''}><b>${i+1}</b><span>🐟</span><small>+7</small></button>`).join('')}</div><button class="primary" id="releaseRainbow" disabled>ปล่อยพลังเกล็ด 56 ชิ้น! ✦</button>`;const fishButtons=[...p.querySelectorAll('[data-fish]')],pattern=[...p.querySelectorAll('[data-pattern]')];fishButtons.forEach((b,i)=>b.onclick=()=>{if(b.disabled)return;b.disabled=true;b.classList.add('lit');fishLit++;rainbowScales+=7;scaleCount.textContent=rainbowScales;fishEquation.childNodes[0].textContent=`${fishLit} × 7 = `;rainbowBar.style.width=`${rainbowScales/56*100}%`;pattern[i].textContent=rainbowScales;pattern[i].classList.add('revealed');tone(420+fishLit*45,.16);if(fishButtons[i+1]){fishButtons[i+1].disabled=false;fishGuide.textContent=`${rainbowScales} แล้ว—ปลาตัวที่ ${fishLit+1} จะเพิ่มอีก 7 เป็นเท่าไรนะ?`}else{releaseRainbow.disabled=false;fishGuide.textContent='ขบวนแม่ 7 ครบแล้ว: 7, 14, 21, 28, 35, 42, 49, 56';fb.innerHTML='<div class="star-chance">ปลาทั้ง 8 ตัวพร้อมแล้ว—ปล่อยเกล็ด 56 ชิ้นสู่น้ำตกได้เลย ✦</div>'}});releaseRainbow.onclick=()=>check(rainbowScales)}
if(l.type==='leaves'){const bundles=[200,50,6],explain=['เพิ่ม 2 ร้อย: 189 + 200 = 389','8 สิบ + 5 สิบ = 13 สิบ จัดกลุ่มใหม่เป็น 1 ร้อย 3 สิบ','9 หน่วย + 6 หน่วย = 15 หน่วย จัดกลุ่มใหม่เป็น 1 สิบ 5 หน่วย'];p.innerHTML=`<div class="leaf-total"><small>ใบไม้ทอง 189 + ใบไม้เงิน 256</small><div class="leaf-place-number" aria-label="จำนวนใบไม้ปัจจุบัน"><span id="leafHundreds">1<small>ร้อย</small></span><span id="leafTens">8<small>สิบ</small></span><span id="leafOnes">9<small>หน่วย</small></span></div><strong id="leafCount">189</strong><p id="carryMessage">เริ่มจากใบไม้ทอง 189 ใบ</p></div><div class="wind-path">${bundles.map((v,i)=>`<span data-wind="${i}"><small>สายลม ${i+1}</small><b>+${v}</b><em>รอถัก</em></span>`).join('')}</div><div class="leaf-bundles">${bundles.map((v,i)=>`<button data-leaf="${i}" data-value="${v}" ${i?'disabled':''}><span>${i?'🍃':'🍁'}</span><b>+${v}</b><small>${['2 ร้อย','5 สิบ','6 หน่วย'][i]}</small></button>`).join('')}</div><button class="primary" id="openLeafGate" disabled>เปิดประตูด้วยใบไม้ 445 ใบ ✦</button>`;const leafButtons=[...p.querySelectorAll('[data-leaf]')],windSteps=[...p.querySelectorAll('[data-wind]')];leafButtons.forEach((b,i)=>b.onclick=()=>{if(b.disabled)return;const before=leafTotal;b.disabled=true;b.classList.add('woven');leafTotal+=+b.dataset.value;leafSteps++;leafCount.textContent=leafTotal;const digits=String(leafTotal).padStart(3,'0').split('');leafHundreds.textContent=digits[0];leafHundreds.insertAdjacentHTML('beforeend','<small>ร้อย</small>');leafTens.textContent=digits[1];leafTens.insertAdjacentHTML('beforeend','<small>สิบ</small>');leafOnes.textContent=digits[2];leafOnes.insertAdjacentHTML('beforeend','<small>หน่วย</small>');carryMessage.textContent=explain[i];windSteps[i].classList.add('woven');windSteps[i].querySelector('em').textContent=`${before} → ${leafTotal}`;tone(460+leafSteps*100,.2);if(leafButtons[i+1])leafButtons[i+1].disabled=false;else{openLeafGate.disabled=false;fb.innerHTML='<div class="star-chance">สายลมทั้งสามถักเสร็จแล้ว—ใบไม้รวม 445 ใบ ✦</div>'}});openLeafGate.onclick=()=>check(leafTotal)}
if(l.type==='sand'){const scoops=[100,40,5];p.innerHTML=`<div class="desert-duel"><div class="shadow-castle" id="shadowCastle"><span>🏰</span><small>ปราสาทเงา</small></div><div class="sand-scale"><small>ทรายเวทมนตร์ที่เหลือ</small><strong><span id="sandCount">600</span> กก.</strong><p id="sandGuide">แยกทรายที่ถูกขโมย 145 = 100 + 40 + 5</p><div><i id="sandBar"></i></div></div><div class="oasis-stage" id="oasisStage"><span>💧</span><small>โอเอซิส</small></div></div><div class="sand-equations">${scoops.map((v,i)=>`<span data-sand-step="${i}"><small>ขั้นที่ ${i+1}</small><b>−${v}</b><em>รอชั่ง</em></span>`).join('')}</div><div class="sand-scoops">${scoops.map((v,i)=>`<button data-sand="${i}" data-value="${v}" ${i?'disabled':''}><span>⌛</span><b>−${v}</b><small>${['1 ร้อย','4 สิบ','5 หน่วย'][i]}</small></button>`).join('')}</div><button class="primary" id="restoreOasis" disabled>คืนทราย 455 กก. ให้อโอเอซิส ✦</button>`;const sandButtons=[...p.querySelectorAll('[data-sand]')],sandStepCards=[...p.querySelectorAll('[data-sand-step]')];sandButtons.forEach((b,i)=>b.onclick=()=>{if(b.disabled)return;const before=sandTotal;b.disabled=true;b.classList.add('poured');sandTotal-=+b.dataset.value;sandSteps++;sandCount.textContent=sandTotal;sandGuide.textContent=`${before} − ${b.dataset.value} = ${sandTotal} กิโลกรัม`;sandStepCards[i].classList.add('weighed');sandStepCards[i].querySelector('em').textContent=`${before} → ${sandTotal}`;sandBar.style.width=`${sandSteps/3*100}%`;oasisStage.className=`oasis-stage stage-${sandSteps}`;shadowCastle.className=`shadow-castle stage-${sandSteps}`;tone(520+sandSteps*80,.2);if(sandButtons[i+1])sandButtons[i+1].disabled=false;else{restoreOasis.disabled=false;sandGuide.textContent='ชั่งครบแล้ว! ทราย 455 กิโลกรัมพร้อมคืนสู่อโอเอซิส';fb.innerHTML='<div class="star-chance">พลังปราสาทเงาอ่อนลง—ปลุกโอเอซิสได้เลย ✦</div>'}});restoreOasis.onclick=()=>check(sandTotal)}
if(l.type==='choice'&&l.id!==4&&l.id!==5){p.innerHTML=l.choices.map(x=>`<button class="choice" data-v="${x}">${x}</button>`).join('');p.querySelectorAll('.choice').forEach(c=>c.onclick=()=>check(c.dataset.v))}}
function finish(l,tries){const result=PROGRESS.completeLevel(save,l,tries,LEVELS.length),{runStars,previousStars,bestStars,savedItem,isNewItem,isRecord}=result;save=result.nextSave;persist();const lootText=isNewItem?`ได้รับ “${l.reward}” · 💎 +10`:`มี “${l.reward}” อยู่แล้ว · ไม่ได้รับผลึกซ้ำ`,lootHeading=isNewItem?'ค้นพบของวิเศษใหม่!':'บันทึกในกระเป๋าแล้ว',lootNote=itemInfo(savedItem).note,starText=!previousStars?`ผ่านครั้งแรก · ได้ ${runStars} ดาว`:isRecord?`สถิติใหม่! ${previousStars} → ${runStars} ดาว`:`รอบนี้ ${runStars} ดาว · สถิติสูงสุด ${bestStars} ดาว`,nextText=l.id===5?'ดูตอนจบ World 1':l.id===10?'ดูตอนจบ World 2':l.id===LEVELS.length?'กลับสู่แผนที่':'เดินทางต่อ';app.insertAdjacentHTML('beforeend',`<div class="reward"><div class="reward-card"><div class="reward-burst reward-art">${itemArt(savedItem)}</div><div class="reward-score"><small>ดาวรอบนี้</small>${starRating(runStars)}<strong class="reward-record ${isRecord?'new-record':''}">${starText}</strong></div><h2>${l.successTitle}</h2><p>${l.success}</p><div class="loot"><strong>${lootHeading}</strong><span>${lootText}</span><small>${lootNote}</small></div><div class="reward-actions"><button class="secondary" id="retry">เล่นอีกครั้ง ↻</button><button class="primary" id="next">${nextText}</button></div></div></div>`);retry.onclick=()=>explore(l.id);next.onclick=()=>l.id===5?story(window.WORLD_ONE_ENDING,map):l.id===10?story(window.WORLD_TWO_ENDING,map):map()}
new MutationObserver(()=>{const reward=document.querySelector('.reward');if(!reward||reward.dataset.accessible)return;reward.dataset.accessible='true';reward.setAttribute('role','dialog');reward.setAttribute('aria-modal','true');reward.setAttribute('aria-label',reward.querySelector('h2')?.textContent||'รางวัลจากการผจญภัย');requestAnimationFrame(()=>reward.querySelector('#next')?.focus())}).observe(app,{childList:true});
new MutationObserver(()=>{const reward=document.querySelector('.reward');if(!reward||reward.dataset.fanfare)return;reward.dataset.fanfare='true';successFanfare()}).observe(app,{childList:true});
const polishThaiCopy=root=>{const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);let node;while(node=walker.nextNode())if(node.nodeValue.includes('อโอเอซิส'))node.nodeValue=node.nodeValue.replaceAll('อโอเอซิส','โอเอซิส')};
new MutationObserver(records=>records.forEach(record=>record.addedNodes.forEach(node=>{if(node.nodeType===Node.TEXT_NODE){if(node.nodeValue.includes('อโอเอซิส'))node.nodeValue=node.nodeValue.replaceAll('อโอเอซิส','โอเอซิส')}else polishThaiCopy(node)}))).observe(app,{childList:true,subtree:true});
